/// <summary>
/// The service class for sales order cancel process.
/// </summary>
class METSalesOrderCancelService extends SysOperationServiceBase
{
}

Method.Source:
    // <summary>
    /// cancels the sales order.
    /// </summary>
    /// <param name="_contract">
    /// The contract instance
    /// </param>
    /// <returns>
    /// The response <c>METSalesOrderCancelResponseContract</c>
    /// </returns>
    public METSalesOrderCancelResponseContract cancelSalesOrder(METSalesOrderCancelContract _contract)
    {
        SalesTable  salesTable;
        SalesId     salesId;
        CustAccount custAccount;
        boolean     salesOrderCancelled;

        METSalesOrderCancelResponseContract response = new METSalesOrderCancelResponseContract();
        #OCCRetryCount

        try
        {
            salesId = _contract.parmSalesId();
            custAccount = _contract.parmCustAccount();

            changecompany(_contract.parmDataAreaId())
            {
                select firstonly salesTable
                    where salesTable.SalesId == salesId
                       && salesTable.CustAccount == custAccount;

                if(salesTable.RecId)
                {
                    if(salesTable.SalesStatus != SalesStatus::Backorder)
                    {
                        response.parmCancelResult(false);
                        response.parmCancelMessage(strFmt("@MET:SalesOrderNotOpen", salesId));

                        return response;
                    }

                    SalesUpdateRemain salesUpdateRemain = SalesUpdateRemain::construct();

                    salesOrderCancelled = salesUpdateRemain.cancelOpenOrderLinesDeliveryRemainder(salesTable);

                    if(salesOrderCancelled)
                    {
                        response.parmCancelResult(true);
                        response.parmCancelMessage("@MET:SalesOrderCancelled");

                    }
                    else
                    {
                        response.parmCancelResult(false);
                        response.parmCancelMessage(strFmt("@MET:SalesCancellationFailed", salesId));

                    }

                }
                else
                {
                    response.parmCancelResult(false);
                    response.parmCancelMessage(strFmt("@MET:SalesOrderNotFound", salesId));

                    return response;

                }

            }
        }
        catch (Exception::Deadlock)
        {
            retry;
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    response.parmCancelResult(false);
                    response.parmCancelMessage("@MET:SalesCancelUpdateConflict");

                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                response.parmCancelResult(false);
                response.parmCancelMessage("@MET:SalesCancelUpdateConflict");

                throw Exception::UpdateConflict;
            }
            
        }
        catch(Exception::CLRError)
        {
            response.parmCancelResult(false);
            response.parmCancelMessage(strFmt("@MET:SalesCancellationFailed", salesId));
        }
        catch(Exception::Error)
        {
            response.parmCancelResult(false);
            response.parmCancelMessage(strFmt("@MET:SalesCancellationFailed", salesId));
        }

        return response;
    }
